// Veloxa's illustration family (original SVGs generated by scripts/gen_art.py, stored in src/assets/art).
// Synthetic agents get an illustrated avatar; anyone else (a real person) gets neutral initials, never a portrait.
const agentArt = import.meta.glob("../assets/art/agents/*.svg", { eager: true, query: "?url", import: "default" }) as
  Record<string, string>;
const deptArt = import.meta.glob("../assets/art/departments/*.svg", { eager: true, query: "?url", import: "default" }) as
  Record<string, string>;

const AGENT_URLS = Object.keys(agentArt).sort().map((k) => agentArt[k]);

// The 14 Demo Lab agents (tests/synthetic_company) each have their own avatar; other synthetic agents hash to one.
const SYNTHETIC_AGENTS = [
  "syn-eng-juniper", "syn-eng-platform", "syn-eng-quartz", "syn-eng-releases", "syn-eng-reliability",
  "syn-fin-cash", "syn-fin-revenue", "syn-fin-vendors", "syn-mkt-campaigns", "syn-mkt-launch", "syn-mkt-pipeline",
  "syn-ppl-headcount", "syn-ppl-hiring", "syn-ppl-org",
];

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function initials(name: string): string {
  return name.replace(/^(syn-|person:)/, "").split(/[-\s_.]+/).filter(Boolean).slice(0, 2)
    .map((w) => w[0]?.toUpperCase()).join("") || "?";
}

/** An agent or person avatar. Illustrations only for synthetic agents (ids starting "syn-"). */
export function AgentAvatar({ id, size = 32 }: { id: string; size?: number }) {
  if (id.startsWith("syn-") && AGENT_URLS.length) {
    const known = SYNTHETIC_AGENTS.indexOf(id);
    const url = AGENT_URLS[known >= 0 ? known : hash(id) % AGENT_URLS.length];
    return <img className="art-avatar" src={url} width={size} height={size} alt="" aria-hidden="true" />;
  }
  return <span className="avatar" style={{ width: size, height: size, fontSize: Math.max(10, size * 0.36) }}
               aria-hidden="true">{initials(id)}</span>;
}

const DEPT_ALIASES: Record<string, string> = { people_ops: "people", "people operations": "people", hr: "people" };

/** A department mark. Unknown departments get a neutral initial tile from the same family. */
export function DeptArt({ id, size = 40 }: { id: string; size?: number }) {
  const key = DEPT_ALIASES[id.toLowerCase()] ?? id.toLowerCase();
  const url = Object.entries(deptArt).find(([k]) => k.endsWith(`/${key}.svg`))?.[1];
  return url ? <img className="art-dept" src={url} width={size} height={size} alt="" aria-hidden="true" />
    : <span className="dept-tile" style={{ width: size, height: size }} aria-hidden="true">{initials(id)}</span>;
}
